#!/bin/bash
X=/private/tmp/claude-501/-Users-demo-Projects-Stage11-code-c11/db1a6a30-772c-4e09-ad72-4ab88398c790/scratchpad; export X
. $X/hcenv.sh; export PRIME_DISABLE_VERSION_CHECK=1
mach() { $HC machine ls --json 2>/dev/null | python3 -I -c "import sys,json; d=json.load(sys.stdin); ms=d.get('machines',[]); print([{k:m.get(k) for k in ['name','state','last_error']} for m in ms])" 2>/dev/null; }
get() { python3 -I $X/hcx.py call terminal.get "{\"terminal\":\"$1\"}" | python3 -I -c "import sys,json; d=json.loads(sys.stdin.read(),strict=False); t=d.get('result',d); print({k:t.get(k) for k in ['address','state','pid','reason','exit_code','foreground']})" 2>/dev/null; }
CREATE=$(prime --plain sandbox create buildpack-deps:bookworm-scm --yes --name c11v-hc-fed3 --label fleet=c11v --cpu-cores 2 --memory-gb 4 --disk-size-gb 10 --timeout-minutes 30 --region us 2>&1); BOX=$(echo "$CREATE" | grep -oE '\b[a-z0-9]{20,}\b' | head -1); echo "BOX=$BOX"; echo "$BOX" > $X/prime-box-id
for i in $(seq 1 30); do ST=$(prime --plain sandbox list --output json 2>/dev/null | python3 -I -c "import sys,json; d=json.load(sys.stdin); d=d if isinstance(d,list) else d.get('sandboxes',d.get('data',[])); print(next((s.get('status') for s in d if s.get('id')=='$BOX'),'?'))" 2>/dev/null); [ "$ST" = "RUNNING" ] && break; sleep 5; done; echo "box $ST $(date +%H:%M:%S)"
mkdir -p /tmp/c11hcx && chmod 700 /tmp/c11hcx; $HC ls --json >/dev/null 2>&1; sleep 0.5; $HC machine add --name box --temp --install --via "prime --plain sandbox ssh $BOX --" --json >/dev/null 2>&1; for i in $(seq 1 20); do M=$(mach); echo "$M" | grep -q "'connected'" && break; sleep 2; done; echo "$(date +%H:%M:%S) $(mach)"
echo "===== remote terminals via the API ====="; python3 -I $X/hcx.py call terminal.run '{"argv":["sleep","3000"],"on":"box","name":"keep","no_parent":true}' | head -c 160; echo; python3 -I $X/hcx.py call terminal.run '{"argv":["/bin/bash","--norc","-i"],"on":"box","name":"rbash","no_parent":true}' | head -c 160; echo; sleep 3; echo "keep:  $(get box/keep)"; echo "rbash: $(get box/rbash)"
echo "--- local ls (remote terminals merged?) ---"; $HC ls --json | python3 -I -c "import sys,json; d=json.loads(sys.stdin.read(),strict=False); print([(t['address'],t.get('name'),t['state']) for t in d['terminals']])"
echo "--- attach box/rbash through the local core: first paint, echo RTT ---"; python3 -I $X/hcx.py paint box/rbash 5 | head -2 | cut -c1-220; python3 -I $X/hcx.py lat box/rbash 150
echo "--- exec on the box + file read ---"; $HC exec --on box uname -a 2>&1 | tail -1; $HC file read --on box /etc/os-release --limit 2 2>&1 | tail -2
echo "===== link drop with an attached viewer ====="; python3 -I $X/evwatch.py 60 > $X/evwatch.out 2>&1 & EVPID=$!; python3 -I $X/attachwatch.py box/rbash > $X/attachwatch.out 2>&1 & AWPID=$!; sleep 3; PRIMEP=$(pgrep -f "prime --plain sandbox ssh $BOX" | head -1); SSHKIDS=$(pgrep -P $PRIMEP | tr '\n' ' '); echo "killing ssh [$SSHKIDS] + wrapper $PRIMEP at $(date +%H:%M:%S)"; kill -9 $SSHKIDS $PRIMEP 2>/dev/null; for i in $(seq 1 8); do sleep 3; echo "  $(date +%H:%M:%S) $(mach)"; done; wait $AWPID; echo "--- attach watcher ---"; cat $X/attachwatch.out; echo "--- after reconnect ---"; echo "rbash: $(get box/rbash)"; python3 -I $X/hcx.py paint box/rbash 0 | head -1; python3 -I $X/hcx.py lat box/rbash 100 2>&1 | tail -1; wait $EVPID; echo "--- events ---"; cat $X/evwatch.out | head -30
echo "===== does the remote core survive the local core stopping? ====="; $HC server stop --json; sleep 2; mkdir -p /tmp/c11hcx; $HC ls --json >/dev/null 2>&1; sleep 1; for i in $(seq 1 15); do M=$(mach); echo "$M" | grep -q "'connected'" && break; sleep 2; done; echo "$(date +%H:%M:%S) $(mach)"; echo "rbash after local core restart: $(get box/rbash)"
echo "===== cleanup ====="; $HC machine rm box --json >/dev/null 2>&1; $HC server stop --json; sleep 2; pkill -9 -f "$X/bin/hc" 2>/dev/null; pkill -9 -f "sandbox ssh $BOX" 2>/dev/null; pgrep -fl "$X/bin/hc" || echo "no hc processes left"; /bin/rm -rf /tmp/c11hcx; prime --plain sandbox delete $BOX --yes 2>&1 | tail -1; prime --plain sandbox list 2>&1 | tail -1
